const refund = (amount: number, note: string) => ({
  capture_id: "CAPTURE", amount: { currency_code: "USD", value: amount.toFixed(2) }, note_to_payer: note,
});
const fullRefund = (note: string) => ({ capture_id: "CAPTURE", note_to_payer: note });
const order = (
  buyer: string, items: [name: string, unit: number, quantity?: number][], shipping: number,
  daysAgo: number, tracking: BenchOrder["tracking"] = "DELIVERED", refunded = 0,
): BenchOrder => ({
  buyer, items: items.map(([name, unit, quantity = 1]) => ({ name, unit, quantity })),
  shipping, daysAgo, tracking, refunded,
});

